    'RegistrationText'=>'पंजीकृत SimpleRisk इंस्टेंस को तुरंत Upgrade और Secure Controls Framework (SCF) Extras तक पहुँच दी जाती है।  Upgrade Extra एक बटन के क्लिक पर आपके SimpleRisk इंस्टेंस का बैकअप लेने और उसे अपग्रेड करने की सुविधा देता है।  Secure Controls Framework (SCF) Extra एक सामान्य नियंत्रण फ्रेमवर्क प्रदान करता है, जो SimpleRisk के शासन संबंधी फ़ंक्शन में एकीकृत है।  SimpleRisk को पंजीकृत करने पर, आपकी पंजीकरण जानकारी SimpleRisk द्वारा होस्ट किए गए सर्वर पर भेजी जाएगी।  दी गई पंजीकरण जानकारी का उपयोग SimpleRisk द्वारा ग्राहकों को नए रिलीज़ और सुरक्षा अपडेट के बारे में सूचित करने के लिए किया जाएगा।  SimpleRisk को पंजीकृत करने से आप हमारे मार्केटिंग संचार के लिए सहमत हो जाएँगे, लेकिन आप इन संचारों में दिए गए अनसब्सक्राइब लिंक का उपयोग करके किसी भी समय इससे बाहर निकल सकते हैं।  SimpleRisk हमारे ग्राहकों की गोपनीयता का सम्मान करता है और SimpleRisk पंजीकरण प्रक्रिया के माध्यम से हमें दी गई जानकारी कभी भी किसी तीसरे पक्ष को नहीं बेची जाएगी।',
