    'AdminRoleDescription' => 'यह अनुमति SimpleRisk के कॉन्फ़िगरेशन तक पहुँच प्रदान करती है। इस अनुमति वाला उपयोगकर्ता प्रभावी रूप से सिस्टम पर एक व्यवस्थापक उपयोगकर्ता होता है। वह "कॉन्फ़िगर करें" मेनू में मौजूद किसी भी और सभी मेनू में बदलाव कर सकता है। इससे Extras को सक्रिय और निष्क्रिय करने तथा उनके कॉन्फ़िगरेशन को संशोधित करने की भी अनुमति मिलेगी। यह अनुमति केवल उन्हीं को दी जानी चाहिए जिन्हें इसकी पूर्ण आवश्यकता हो। एक बार किसी उपयोगकर्ता को इस अनुमति की पहुँच मिल जाने पर, वह अन्य उपयोगकर्ता खातों को भी संपादित कर सकेगा।',
