    'IncidentUpdatePermissionMessage' => 'आपको घटनाओं को संशोधित करने की अनुमति नहीं है। आपके द्वारा संशोधित करने का कोई भी प्रयास रिकॉर्ड नहीं किया जाएगा। यदि आपको लगता है कि आपको यह संदेश त्रुटि से मिला है, तो कृपया किसी प्रशासक से संपर्क करें।',
    'IncidentPreparationPermissionMessage' => 'आपके पास घटना तैयारी आइटम चुनने की अनुमति नहीं है। आपके द्वारा चुने जाने का प्रयास किया गया कोई भी आइटम रिकॉर्ड नहीं किया जाएगा। यदि आपको लगता है कि आपको यह संदेश त्रुटि से प्राप्त हुआ है, तो कृपया किसी व्यवस्थापक से संपर्क करें।',
    'IncidentPlaybookSelectPermissionMessage' => 'आपको रोकथाम, उन्मूलन और पुनर्प्राप्ति चरणों को निर्धारित करने के लिए घटना प्रतिक्रिया प्लेबुक का चयन करने की अनुमति नहीं है। यदि आपको लगता है कि आपको यह संदेश गलती से प्राप्त हुआ है, तो कृपया किसी प्रशासक से संपर्क करें।',
    'IncidentResponseSelectPermissionMessage' => 'आपके पास नियंत्रण-सीमा (Containment), उन्मूलन (Eradication) और पुनर्प्राप्ति (Recovery) चरणों से घटना प्रतिक्रिया प्लेबुक आइटम चुनने की अनुमति नहीं है। आपके द्वारा चुने जाने का प्रयास किया गया कोई भी आइटम रिकॉर्ड नहीं किया जाएगा। यदि आपको लगता है कि आपको यह संदेश त्रुटि से प्राप्त हुआ है, तो कृपया किसी व्यवस्थापक से संपर्क करें।',
    'IncidentResponseEvidenceAddPermissionMessage' => 'आपके पास किसी घटना में साक्ष्य जोड़ने की अनुमति नहीं है। जोड़ा गया कोई भी साक्ष्य रिकॉर्ड नहीं किया जाएगा। यदि आपको लगता है कि आपको यह संदेश त्रुटि से प्राप्त हुआ है, तो कृपया किसी व्यवस्थापक से संपर्क करें।',
    'IncidentResponseEvidenceDeletePermissionMessage' => 'आपके पास किसी घटना से साक्ष्य हटाने की अनुमति नहीं है। यदि आपको लगता है कि आपको यह संदेश त्रुटि से प्राप्त हुआ है, तो कृपया किसी व्यवस्थापक से संपर्क करें।',
    'IncidentResponseNoteAddPermissionMessage' => 'आपको किसी घटना में नोट्स जोड़ने की अनुमति नहीं है। जोड़े गए नोट्स रिकॉर्ड नहीं किए जाएंगे। यदि आपको लगता है कि आपको यह संदेश गलती से प्राप्त हुआ है, तो कृपया किसी प्रशासक से संपर्क करें।',
