    'AllOpenRisksByTeamByLevelDesc'           => 'स्वामित्व रिपोर्टिंग के लिए जोखिमों को पहले टीम के अनुसार, फिर जोखिम स्तर के अनुसार वर्गीकृत किया जाता है।',
