    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'सिस्टम-व्यापी सेटिंग्स कॉन्फ़िगर करें: बेस URL, सुरक्षा, डिफ़ॉल्ट भाषा, समय क्षेत्र, जोखिम स्कोरिंग डिफ़ॉल्ट, और बहुत कुछ।',
    'SettingsPreferencesDesc'             => 'SimpleRisk में डिफ़ॉल्ट मान और व्यवहार संबंधी प्राथमिकताएँ: भाषा, समय क्षेत्र, ऑडिट स्थितियाँ, जोखिम-मैपिंग आवश्यकताएँ, UI व्यवहार टॉगल, और इसी प्रकार की अन्य।',
    'SettingsFileUploadDesc'              => 'विभिन्न फ़ाइल अटैचमेंट फ़ील्ड के लिए अनुमत फ़ाइल अपलोड प्रकार और आकार सीमाएँ।',
    'SettingsMailDesc'                    => 'आउटबाउंड ईमेल सूचनाओं के लिए SMTP कॉन्फ़िगरेशन, जिसमें ट्रांसपोर्ट, होस्ट, प्रमाणीकरण और रिप्लाई-टू शामिल हैं।',
    'SettingsBackupsDesc'                 => 'SimpleRisk डेटाबेस बैकअप के लिए बैकअप प्रतिधारण, शेड्यूल और डाउनलोड लिंक कॉन्फ़िगर करें।',
    'SettingsSecurityDesc'                => 'प्रमाणीकरण, सत्र, पासवर्ड नीति, बेस URL और API सुरक्षा सेटिंग्स।',
    'SettingsLoggingDesc'                 => 'डीबग और ऑडिट लॉगिंग कॉन्फ़िगरेशन: लॉग स्तर, प्रतिधारण और लॉग फ़ाइलों का स्थान।',
    'HealthCheckDesc'                     => 'सिस्टम की स्थिति का निदान करें: PHP संस्करण, एक्सटेंशन, फ़ाइल अनुमतियाँ, डेटाबेस कनेक्टिविटी, क्रॉन शेड्यूल और एक्स्ट्रा सक्रियण।',
    'AnnouncementsDesc'                   => 'सभी उपयोगकर्ताओं को दिखने वाली बैनर घोषणाएँ बनाएँ और प्रबंधित करें।',
    'RegisterAndUpgradeDesc'              => 'अपने SimpleRisk इंस्टॉलेशन को रजिस्टर करें, सब्सक्रिप्शन कुंजी दर्ज करें या नवीनीकृत करें, और एक-क्लिक कोर/एक्स्ट्रा अपग्रेड को सक्रिय करें।',
    'QueueMonitorDesc'                    => 'बैकग्राउंड-जॉब कतार का निरीक्षण करें: लंबित, प्रगति में और विफल जॉब।',
    'ExtrasDesc'                          => 'SimpleRisk Extras (पेड ऐड-ऑन) को सक्रिय, निष्क्रिय और कॉन्फ़िगर करें।',
    'ArtificialIntelligenceExtraDesc'     => 'आर्टिफिशियल इंटेलिजेंस एक्स्ट्रा उन्नत जोखिम विश्लेषण (जिसमें FAIR आकलन शामिल हैं) और अनुकूलित दस्तावेज़ीकरण प्रदान करता है।',
    'CustomizationExtraDesc'              => 'Customization Extra विभिन्न प्रकार के फ़ील्ड जोड़ने और हटाने तथा गतिशील रूप से कस्टम पृष्ठ टेम्पलेट बनाने की क्षमता सक्षम करता है।',
    'NotificationExtraDesc'               => 'Email Notification Extra SimpleRisk को यह सक्षम बनाता है कि जब जोखिम सबमिट किए जाएँ, संशोधित किए जाएँ या उन पर कोई अन्य कार्रवाई की जाए, तब वह ईमेल सूचनाएँ भेज सके। इस Extra को शेड्यूल्ड स्क्रिप्ट के रूप में भी जोड़ा जा सकता है, ताकि जोखिम प्रबंधन समीक्षा के लिए तैयार होने पर नियमित अनुस्मारक भेजे जा सकें। SimpleRisk Core उत्पाद में, इस Extra के बिना, टूल के बाहर कोई सूचना नहीं भेजी जाती।',
    'VulnerabilityManagementExtraDesc'    => 'Vulnerability Management Extra ग्राहकों को अपने SimpleRisk इंस्टेंस को Qualys, Tenable.io या Rapid7 Nexpose/InsightVM के साथ एकीकृत करने और संपत्ति तथा भेद्यता दोनों डेटा को SimpleRisk में आयात करने की क्षमता प्रदान करता है। इसके बाद, आप चुन सकते हैं कि कौन सी साइटें कवर करनी हैं, कौन से भेद्यता स्कोर आयात किए जाएँ, और किन भेद्यताओं को ट्रैक करने के लिए जोखिमों में बदला जाए, इसका ट्रायाज कर सकते हैं।',
    'IncidentManagementExtraDesc'         => 'Incident Management Extra NIST 800-61 Computer Security Incident Handling Guide पर आधारित है और SimpleRisk सिस्टम के भीतर ही घटना प्रबंधन क्षमताएँ प्रदान करता है।',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'पूरे UI में SimpleRisk की शब्दावली (जोखिम, संपत्ति, फ़्रेमवर्क आदि) का नाम बदलें।',
    'RiskConfigurationDesc'               => 'जोखिम स्कोरिंग नियमों को कॉन्फ़िगर करें: स्तर, जोखिम लेने की क्षमता, एसएलए सीमाएँ, और क्लासिक/योगदान देने वाले जोखिम सूत्र।',
    'RiskAndThreatCatalogDesc'            => 'ड्रॉपडाउन में उपयोग होने वाले जोखिम और खतरे के मानों का कैटलॉग बनाए रखें।',
    'AddAndRemoveValuesDesc'              => 'जोखिम फ़ील्ड के ड्रॉपडाउन मान प्रबंधित करें: स्थान, स्रोत, श्रेणी, टीम, प्रौद्योगिकी, और बहुत कुछ।',
    'AssetValuationDesc'                  => 'परिसंपत्ति मूल्यांकन पैमाने और प्रति-परिसंपत्ति मूल्यांकन ओवरराइड को कॉन्फ़िगर करें।',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'उपयोगकर्ताओं को जोड़ें, संपादित करें, अक्षम करें और रीसेट करें; पासवर्ड नीति प्रबंधित करें।',
    'RoleManagementDesc'                  => 'भूमिकाओं और प्रत्येक भूमिका द्वारा प्रदान की जाने वाली अनुमतियों को परिभाषित करें।',
    'TeamManagementDesc'                  => 'रिकॉर्ड दृश्यता फ़िल्टरिंग के लिए उपयोग की जाने वाली टीमें बनाएँ और प्रबंधित करें।',
    'SeparationExtraDesc'                 => 'Team-Based Separation Extra जोखिम देखने को केवल उन उपयोगकर्ताओं तक सीमित करता है जो उस टीम के सदस्य हैं जिसे जोखिम सौंपा गया है। SimpleRisk Core उत्पाद में, इस Extra के बिना, प्रत्येक उपयोगकर्ता हर जोखिम देख सकता है।',
    'CustomAuthenticationExtraDesc'       => 'Custom Authentication Extra Active Directory और SAML प्रमाणीकरण के लिए समर्थन प्रदान करता है। SimpleRisk Core उत्पाद में, इस Extra के बिना, एकमात्र विकल्प SimpleRisk पहचान रिपॉजिटरी में नए उपयोगकर्ता बनाना है।',
    'EncryptionExtraDesc'                 => 'Encrypted Database Extra एक यादृच्छिक AES-256 बिट एन्क्रिप्शन कुंजी उत्पन्न करता है और फिर उसका उपयोग संवेदनशील टेक्स्ट को SimpleRisk डेटाबेस में डालने से पहले एन्क्रिप्ट करने के लिए करता है। यह किसी को भी SimpleRisk एप्लिकेशन का सीधे उपयोग किए बिना डेटा देखने या संशोधित करने से रोकता है।',
    'OrganizationManagementDesc'          => 'Organizational Hierarchy Extra कई बिज़नेस यूनिट परिभाषित करने की क्षमता सक्षम करता है, जिनमें कितनी भी टीमें शामिल हो सकती हैं। इसके बाद उपयोगकर्ताओं को विभिन्न बिज़नेस यूनिट के अंतर्गत एक या अधिक टीमों में असाइन किया जा सकता है। यह उन टीमों, उपयोगकर्ताओं और संपत्तियों को देखने और उपयोग करने की उपयोगकर्ता की क्षमता को प्रभावित करता है जिनसे वे संबद्ध नहीं हैं।',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'जोखिमों को एक साथ हटाएँ। इसका उपयोग सोच-समझकर करें — हटाए गए जोखिम स्थायी रूप से मिट जाते हैं।',
    'AuditTrailDesc'                      => 'उपयोगकर्ता की गतिविधियों के सिस्टम ऑडिट लॉग को खोजें और निर्यात करें।',
    'ImportExportExtraDesc'               => 'Import-Export Extra CSV फ़ाइल के फ़ील्ड को SimpleRisk डेटाबेस के फ़ील्ड से मैप करके SimpleRisk में डेटा आयात करने की क्षमता प्रदान करता है। इसका उपयोग किसी थर्ड-पार्टी स्प्रेडशीट से ऑडिट परिणाम, किसी अन्य टूल से भेद्यता स्कैन परिणाम, आपके CMDB से संपत्तियाँ और बहुत कुछ आयात करने के लिए किया जा सकता है। यह Extra SimpleRisk से जोखिम, शमन, समीक्षाएँ, या तीनों की संयुक्त रिपोर्ट वाली CSV फ़ाइलें निर्यात करने की क्षमता भी प्रदान करता है।',
    'JiraExtraDesc'                       => 'Jira Integration Extra उपयोगकर्ताओं को Jira इंस्टेंस के साथ द्वि-दिशात्मक रूप से एकीकृत करने की क्षमता प्रदान करता है। यह जोखिमों को जीरा मुद्दों से जोड़ने के साथ-साथ उनके डेटा, स्थिति और टिप्पणियों को सिंक करने में सक्षम बनाता है।',
    'APIExtraDesc'                        => 'API Extra ग्राहकों को अन्य एप्लिकेशन के साथ स्क्रिप्टेड इंटरैक्शन बनाने के लिए RESTful API का उपयोग करने की अनुमति देता है, ताकि उन्नत स्वचालन प्राप्त हो और मौजूदा इंफ्रास्ट्रक्चर का लाभ उठाया जा सके।',
    'AdvancedSearchExtraDesc'             => 'Advanced Search Extra शीर्ष बार के खोज बॉक्स को जोखिमों, फ़्रेमवर्क, नियंत्रणों, दस्तावेज़ों, अपवादों, परीक्षणों, ऑडिट, संपत्तियों और संपत्ति समूहों में एकल खोज में बदल देता है, और परिणामों पर काम करने के लिए एक पूर्ण खोज पृष्ठ प्रदान करता है। यह केवल वही रिकॉर्ड दिखाता है जिन्हें उपयोगकर्ता देख सकता है।',
    'AssessmentsExtraDesc'                => 'Risk Assessment Extra उपयोगकर्ताओं को संपर्क परिभाषित करने, प्रश्न (तर्क सहित) बनाने, प्रश्नावली टेम्पलेट के साथ कई प्रश्नों को संयोजित करने, प्रश्नावली बनाने और उन्हें संपर्कों को भेजने, प्रश्नावली परिणाम देखने, उन परिणामों के आधार पर जोखिम जोड़ने, समय के साथ परिणामों की तुलना करने, बाहरी रूप से अनुकूलित मूल्यांकन आयात और निर्यात करने, और जोखिम मूल्यांकन ऑडिट ट्रेल की समीक्षा करने की क्षमता प्रदान करता है।',
    'ActiveAssessmentsDesc'               => 'वर्तमान में चल रहे मूल्यांकनों को देखें और प्रबंधित करें।',
    'WorkflowsExtraDesc'                  => 'वर्कफ़्लो एक्स्ट्रा एक विज़ुअल, इवेंट-ड्रिवन वर्कफ़्लो इंजन प्रदान करता है जो SimpleRisk के भीतर होने वाली घटनाओं के आधार पर जोखिम प्रबंधन कार्यों को स्वचालित करता है। आप ऐसे वर्कफ़्लो डिज़ाइन कर सकते हैं जो परिवर्तनों के आधार पर सक्रिय होते हैं — जैसे कि किसी जोखिम का सबमिट होना, अपडेट होना या समीक्षा होना — ताकि अनुमोदन को रूट किया जा सके, कार्य सौंपा जा सके और मैन्युअल हस्तक्षेप के बिना आपकी प्रक्रिया सुचारू रूप से चलती रहे।',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Secure Controls Framework (SCF) Extra, Secure Controls Framework और SimpleRisk के बीच एक सीधा एकीकरण है। यह SCF के नियंत्रणों की सूची और अनुपालन तथा साइबर सुरक्षा फ्रेमवर्क की विस्तृत श्रृंखला में उनकी मैपिंग को SimpleRisk की शासन कार्यक्षमता में आयात करता है, ताकि आप अपनी आवश्यकता के फ्रेमवर्क अपना सकें और उनके नियंत्रणों को हाथ से बनाए बिना प्रबंधित कर सकें।',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'पुराने varchar समीक्षा-तिथि कॉलम को उचित दिनांक प्रकारों में माइग्रेट करें। यह केवल आवश्यकता पड़ने पर ही दिखाई देगा।',
    'DatabaseUpgradeDesc'                 => 'SimpleRisk डेटाबेस अपग्रेड रूटीन को मैन्युअल रूप से ट्रिगर करें।',

