    'Scoring' => 'स्कोरिंग',
    'EncryptionMissingLockTablesPrivilege'   => 'SimpleRisk डेटाबेस उपयोगकर्ता के पास LOCK TABLES विशेषाधिकार नहीं है, जो डेटाबेस को सुरक्षित रूप से एन्क्रिप्ट करने के लिए आवश्यक है। किसी डेटाबेस व्यवस्थापक से प्रतिक्रिया में लौटाया गया GRANT स्टेटमेंट चलवाएँ और पुनः प्रयास करें।',
    'EncryptionMissingLockTablesPrivilegeUi' => 'SimpleRisk डेटाबेस उपयोगकर्ता के पास एन्क्रिप्शन के लिए आवश्यक LOCK TABLES विशेषाधिकार नहीं है। डेटाबेस व्यवस्थापक को यह चलाना होगा: GRANT LOCK TABLES ON {$db}.* TO {$user}; फिर पुनः प्रयास करें।',
    'EncryptionRequiredGrantLabel' => 'आवश्यक GRANT कथन:',
    'EncryptionActivationAlreadyRunning' => 'एन्क्रिप्शन सक्रियण पहले से ही प्रगति पर है। इसके पूरा होने की प्रतीक्षा करें या पुनर्प्राप्त करने के लिए बैकअप से पुनर्स्थापित करें का उपयोग करें।',
    'EncryptionActivationEnqueued'           => 'एन्क्रिप्शन Extra का सक्रियण कतार में जोड़ दिया गया है। डेटाबेस के एन्क्रिप्ट होने के दौरान व्यवस्थापक UI प्रगति को ट्रैक करेगा।',
    'EncryptionActivationEnqueueFailed'      => 'एन्क्रिप्शन सक्रियण कार्य को कतार में जोड़ना विफल रहा। विवरण के लिए डीबग लॉग की जाँच करें।',
    'EncryptionDeactivationEnqueued'         => 'एन्क्रिप्शन Extra का निष्क्रियकरण कतार में जोड़ दिया गया है। डेटाबेस के डिक्रिप्ट होने के दौरान व्यवस्थापक UI प्रगति को ट्रैक करेगा।',
    'EncryptionDeactivationEnqueueFailed'    => 'एन्क्रिप्शन निष्क्रियकरण कार्य को कतार में जोड़ना विफल रहा। विवरण के लिए डीबग लॉग की जाँच करें।',
    'EncryptionPipelineInProgress'           => 'एक एन्क्रिप्शन पाइपलाइन (सक्रिय करना, निष्क्रिय करना या पुनर्स्थापित करना) वर्तमान में प्रगति पर है। पुनः प्रयास करने से पहले इसके समाप्त होने की प्रतीक्षा करें।',
