    'EncryptionDeactivateCtaHelp'           => 'प्रत्येक एन्क्रिप्टेड कॉलम को वापस सादे पाठ में डिक्रिप्ट करें। अधिक डेटा वाले डेटाबेस में इसमें कई मिनट लगते हैं।',
