    'EncryptionBackupOriginalFilename'      => 'फ़ाइल',
    'EncryptionBackupDownloadTooltip'       => 'इस बैकअप फ़ाइल की एक प्रति ऑफ़लाइन संग्रहण के लिए डाउनलोड करने के लिए क्लिक करें।',
    'EncryptionBackupStateRestoring'        => 'पुनर्स्थापना वर्तमान में प्रगति पर है।',
    'EncryptionNoBackupAvailable'           => 'वर्तमान में कोई सक्रियण-पूर्व बैकअप संग्रहीत नहीं है। बैकअप प्रत्येक सक्रियण की शुरुआत में बनाया जाता है और किसी भी बाद के सक्रियण या निष्क्रियण द्वारा अधिलेखित कर दिया जाता है।',
    'EncryptionRestoreCtaHelp'              => 'यदि सत्यापन में कोई समस्या पाई जाती है और आपको एन्क्रिप्शन से पहले की स्थिति में वापस जाना है, तो इसे चुनें।',
    'EncryptionRestoreTitle'                => 'बैकअप से पुनर्स्थापित करें?',
    'EncryptionRestoreBodyWhy'              => 'सबसे हालिया सक्रियण की शुरुआत में लिए गए पूर्व-एन्क्रिप्शन स्नैपशॉट पर वापस जाना। यदि सक्रियण के बाद किए गए सत्यापन में समस्याएँ पाई गईं और आपको एन्क्रिप्शन बंद करने की आवश्यकता है, तो इसे चुनें।',
    'EncryptionRestoreBodyWhat'             => 'बैकअप बनने के बाद डेटाबेस में लिखी गई प्रत्येक पंक्ति स्थायी रूप से खो जाएगी — इसमें जोखिम, शमन, ऑडिट-लॉग प्रविष्टियाँ और सक्रियण के बाद किए गए अन्य सभी परिवर्तन शामिल हैं। पुनर्स्थापना के भाग के रूप में एन्क्रिप्टेड डेटाबेस Extra निष्क्रिय कर दिया जाएगा।',
    'EncryptionDeleteBackupCta'             => 'एन्क्रिप्शन से पहले के बैकअप को हटा दें',
    'EncryptionDeleteBackupCtaHelp'         => 'एन्क्रिप्शन के बाद सत्यापन पूरा होने पर इसे चुनें। बिना एन्क्रिप्ट किए स्नैपशॉट को हटाना ही एन्क्रिप्शन को वास्तव में सुरक्षात्मक बनाता है।',
    'EncryptionDeleteBackupTitle'           => 'क्या एन्क्रिप्शन से पहले का बैकअप हटा दें?',
    'EncryptionDeleteBackupBodyWhy'         => 'सबसे हाल के सक्रियण की शुरुआत में लिया गया आपके डेटा का अनएन्क्रिप्टेड स्नैपशॉट हटाया जा रहा है। इसे अनिश्चित काल तक रखने से एन्क्रिप्शन का उद्देश्य विफल हो जाता है — डेटाबेस तक पहुँच रखने वाला कोई भी व्यक्ति एन्क्रिप्शन-पूर्व प्रति पढ़ सकता है।',
    'EncryptionDeleteBackupBodyWhat'        => 'डेटाबेस के भीतर का बैकअप तुरंत हटा दिया जाता है। इसके बाद आप डेटाबेस को एन्क्रिप्शन-पूर्व स्थिति में वापस ले जाने के लिए "बैकअप से पुनर्स्थापित करें" का उपयोग नहीं कर पाएँगे। यदि आपको बाद में एन्क्रिप्शन में समस्याएँ मिलती हैं, तो पुनर्प्राप्ति का आपका एकमात्र रास्ता आपके परिचालन बैकअप से नया डेटाबेस पुनर्स्थापित करना होगा।',
    'EncryptionDeleteBackupError'           => 'बैकअप हटाने में विफल। डीबग लॉग की जाँच करें और पुनः प्रयास करें।',
    'EncryptionModalWhyLabel'               => 'इसका उपयोग क्यों करें:',
    'EncryptionModalWhatHappensLabel'       => 'आगे क्या होगा:',
