    'IsmsScopeStatementHint' => 'वह कार्यक्षेत्र जिसके विरुद्ध यह फ़्रेमवर्क प्रमाणित है। यह SoA के कवर पृष्ठ पर दिखाई देता है।',
    'DefaultInclusionJustification' => 'डिफ़ॉल्ट समावेशन औचित्य',
    'DefaultInclusionJustificationHint' => 'उन प्रयोज्य नियंत्रणों के लिए उपयोग किया जाता है जिनसे कोई जोखिम लिंक नहीं है। फ़्रेमवर्क का नहीं, बल्कि प्रेरक कारक का नाम लिखें।',
    // THE DEFAULT SENTENCE, in all three of its roles: the create form seeds the
