    'ApplicabilityNotApplicableHint' => 'किसी नियंत्रण को इस फ़्रेमवर्क के कार्यक्षेत्र से बाहर रखना। कारण और लिखित औचित्य दोनों आवश्यक हैं।',
    'ApplicabilityInheritedHint' => 'कोई और आपकी ओर से यह नियंत्रण निष्पादित करता है। उसका नाम लिखें और बताएं कि वह क्या करता है।',
    'ApplicabilityNarrativeHint' => 'प्रयोज्यता विवरण में दिखाई देता है। लेखा परीक्षक को निर्णय स्वीकार करने के लिए किन बातों की आवश्यकता होगी, यह लिखें।',
