    'FrameworkStatusHint' => 'निष्क्रिय फ़्रेमवर्क अपने सभी नियंत्रण और मैपिंग बनाए रखते हैं, लेकिन डिफ़ॉल्ट फ़्रेमवर्क सूची से छिपे रहते हैं और शासन डैशबोर्ड में शामिल नहीं किए जाते। किसी फ़्रेमवर्क को निष्क्रिय करने से उसके अंतर्गत आने वाले सभी फ़्रेमवर्क भी निष्क्रिय हो जाते हैं; किसी को सक्रिय करने से उसके पैरेंट भी सक्रिय हो जाते हैं।',

    // Task 60: the same #applicability--set modal, opened from ONE control's row
