    'SetApplicabilityForControl' => 'प्रयोज्यता निर्धारित करें: {$name}',
    'ApplicabilityAppliesToControl' => 'इसे केवल "{$name}" के विरुद्ध ही रिकॉर्ड किया जाएगा।',

