    'GetFrameworkFromScf' => 'Secure Controls Framework से एक प्राप्त करें',
    'GetFrameworkFromScfHint' => 'प्रकाशित framework चुनें और उसके मैप किए गए नियंत्रण एक ही चरण में लोड करें।',
    'ImportFrameworkFromCatalog' => 'एक आयात करें',
    'ImportFrameworkFromCatalogHint' => 'SimpleRisk सामग्री कैटलॉग से कोई framework और उसके नियंत्रण स्थापित करें।',

    // The framework acquisition chooser's third route, which now offers the
