    'RiskImportSummary' => '{$submitted} जोखिम प्रस्तुत किए गए और {$updated} जोखिम अपडेट किए गए।',
    'ControlImportSummary' => '{$created} नियंत्रण बनाए गए और {$updated} नियंत्रण अपडेट किए गए।',
    'ImportAdditionalIssuesSuppressed' => '{$count} अतिरिक्त पंक्ति(यों) में समस्याएँ थीं जिन्हें यहाँ अलग से नहीं दिखाया गया है।',
    'EncryptionPipelineStalledTask' => 'एक एन्क्रिप्शन पाइपलाइन (कार्य #{$id}, {$type}) रुकी हुई प्रतीत होती है — यह असामान्य रूप से लंबे समय से बिना प्रगति के {$status} है। इसका आमतौर पर मतलब है कि बैकग्राउंड कतार वर्कर नहीं चल रहा है; जाँच करें कि वह शेड्यूल किया गया है, फिर रुके हुए कार्य के प्रोसेस हो जाने के बाद पुनः प्रयास करें।',
    'EncryptionPipelineStalledState' => 'एक एन्क्रिप्शन पाइपलाइन रुकी हुई प्रतीत होती है — इसे असामान्य रूप से लंबे समय से प्रगति में चिह्नित किया गया है, जबकि इंगित करने के लिए कोई मेल खाता बैकग्राउंड कार्य नहीं है। इसका आमतौर पर मतलब है कि कतार वर्कर नहीं चल रहा है, या पिछली पाइपलाइन इसे सही ढंग से अपडेट किए बिना समाप्त हो गई। पुनः प्रयास करने से पहले डीबग लॉग की जाँच करें।',
    // DEMO_MODE — shown when a visitor to a shared demo instance attempts one
