    'UpgradeExtraDamagedRepaired' => 'अपग्रेड एक्स्ट्रा को एक कार्यशील कॉपी से बदल दिया गया।',
    'UpgradeExtraDamagedFailed' => 'Upgrade Extra क्षतिग्रस्त है और स्वचालित रूप से बदला नहीं जा सका। इसे Extras पृष्ठ से पुनः इंस्टॉल करें, या simplerisk/extras/upgrade/ को बैकअप से पुनर्स्थापित करें, फिर पुनः प्रयास करें।',
    'UpgradeAlreadyCurrent' => 'यह इंस्टेंस पहले से {version} पर है, जो सबसे नवीनतम रिलीज़ है। अपग्रेड करने के लिए कुछ नहीं था।',
