    'RestoreTemplateConfirmBodyRisk' => 'यह विवरण, शमन और समीक्षा टैब के प्रत्येक फ़ील्ड को इस टेम्पलेट समूह के लिए उनके डिफ़ॉल्ट मानों पर रीसेट कर देता है। अन्य टेम्पलेट समूह प्रभावित नहीं होते हैं।',
    'RestoreTemplateConfirmBody' => 'यह इस टेम्पलेट के प्रत्येक फ़ील्ड को इस टेम्पलेट समूह के लिए उसके डिफ़ॉल्ट मानों पर रीसेट कर देता है। अन्य टेम्पलेट समूह प्रभावित नहीं होते हैं।',
    // CVSS holder's collapsed Temporal/Environmental/Impact-Modifiers
