    // (scss/modules/_questionnaire.scss) -- plain text throughout, no HTML,
    // so the popover stays initialized without Bootstrap's `html: true`.
    "AttackVectorHelp" => 'भेद्यता तक किस तरह पहुँचा जा सकता है।
• स्थानीय: स्थानीय पहुँच आवश्यक है, जैसे कंसोल या शेल।
• निकटवर्ती नेटवर्क: हमलावर को उसी भौतिक या तार्किक नेटवर्क खंड में होना चाहिए।
• नेटवर्क: नेटवर्क के माध्यम से दूर से शोषण संभव है, किसी स्थानीय या निकटवर्ती पहुँच की आवश्यकता नहीं।',
    "AttackComplexityHelp" => 'लक्ष्य तक पहुँच मिलने के बाद हमला कितना जटिल है।
