• मध्यम: कुछ शर्तें पूरी होनी चाहिए, लेकिन उनके पूरी होने पर शोषण कठिन नहीं है।
• निम्न: किसी विशेष शर्त की आवश्यकता नहीं है।',
    "AuthenticationHelp" => 'शोषण के लिए हमलावर को लक्ष्य पर कितनी बार प्रमाणीकरण करना होगा।
• एकाधिक: प्रमाणीकरण दो या अधिक बार आवश्यक है, भले ही क्रेडेंशियल समान हों।
• एकल: प्रमाणीकरण एक बार आवश्यक है।
• कोई नहीं: किसी प्रमाणीकरण की आवश्यकता नहीं है।',
    "ConfidentialityImpactHelp" => 'शोषण होने पर सिस्टम द्वारा प्रोसेस किए जाने वाले डेटा की गोपनीयता पर प्रभाव।
• कोई नहीं: कोई प्रभाव नहीं।
• आंशिक: कुछ जानकारी का प्रकटीकरण, लेकिन हमलावर यह नियंत्रित नहीं करता कि कौन सी, या हानि सीमित है।
• पूर्ण: सिस्टम की सारी जानकारी का पूर्ण प्रकटीकरण।',
    "IntegrityImpactHelp" => 'शोषण होने पर सिस्टम की अखंडता पर प्रभाव।
• कोई नहीं: कोई प्रभाव नहीं।
• आंशिक: कुछ डेटा संशोधित किया जा सकता है, लेकिन हमलावर यह नियंत्रित नहीं करता कि कौन सा, या दायरा सीमित है।
• पूर्ण: सिस्टम की अखंडता से पूरी तरह समझौता; हमलावर किसी भी फ़ाइल को संशोधित कर सकता है।',
    "AvailabilityImpactHelp" => 'शोषण होने पर सिस्टम की उपलब्धता पर प्रभाव।
• कोई नहीं: कोई प्रभाव नहीं।
• आंशिक: प्रदर्शन में कमी या उपलब्धता में रुकावटें।
• पूर्ण: प्रभावित संसाधन का पूरी तरह बंद हो जाना।',
    "RemediationLevelHelp" => "इस भेद्यता के लिए उपलब्ध निवारण का स्तर।\n• आधिकारिक समाधान: एक पूर्ण विक्रेता समाधान उपलब्ध है।\n• अस्थायी समाधान: एक आधिकारिक लेकिन अस्थायी समाधान उपलब्ध है।\n• वैकल्पिक समाधान: एक अनौपचारिक, गैर-विक्रेता वैकल्पिक समाधान मौजूद है।\n• अनुपलब्ध: कोई समाधान उपलब्ध नहीं है, या कोई भी लागू नहीं किया जा सकता है।",
    "ReportConfidenceHelp" => 'भेद्यता के अस्तित्व में विश्वास की डिग्री और उसके तकनीकी विवरण की विश्वसनीयता।
• अपुष्ट: एकल, अपुष्ट स्रोत की रिपोर्ट; मूल समस्या अनुमान पर आधारित है।
• असमर्थित: कई स्वतंत्र स्रोत समान व्यवहार की रिपोर्ट करते हैं, लेकिन मूल कारण की पुष्टि नहीं हुई है।
• पुष्ट: विक्रेता ने समस्या स्वीकार की है, या स्रोत-कोड अथवा एक्सप्लॉइट विश्लेषण से इसकी पुष्टि हुई है।',
    "CollateralDamagePotentialHelp" => 'भेद्यता का शोषण होने पर जान, भौतिक परिसंपत्तियों की हानि या वित्तीय हानि की संभावना।
• कोई नहीं: ऐसी किसी हानि की संभावना नहीं है।
• निम्न से मध्यम: मध्यम हानि संभव है।
• उच्च: संगठन की परिसंपत्तियों, राजस्व या सुरक्षा पर विनाशकारी प्रभाव।',
    "TargetDistributionHelp" => 'आपके परिवेश में भेद्य सिस्टम का अनुपात।
• कोई नहीं: कोई लक्षित सिस्टम मौजूद नहीं है।
• निम्न: 1-25% सिस्टम भेद्य हैं।
• मध्यम: 26-75% भेद्य हैं।
• उच्च: 76-100% भेद्य हैं।',
    "ConfidentialityRequirementHelp" => 'प्रभावित परिसंपत्ति की गोपनीयता आपके संगठन के लिए कितनी महत्वपूर्ण है।
• निम्न: गोपनीयता की हानि का सीमित प्रभाव होता है।
• मध्यम: इसका गंभीर प्रभाव होता है।
• उच्च: इसका विनाशकारी प्रभाव होता है।',
    "IntegrityRequirementHelp" => 'प्रभावित परिसंपत्ति की अखंडता आपके संगठन के लिए कितनी महत्वपूर्ण है।
• निम्न: अखंडता की हानि का सीमित प्रभाव होता है।
• मध्यम: इसका गंभीर प्रभाव होता है।
• उच्च: इसका विनाशकारी प्रभाव होता है।',
    "AvailabilityRequirementHelp" => 'प्रभावित परिसंपत्ति की उपलब्धता आपके संगठन के लिए कितनी महत्वपूर्ण है।
• निम्न: उपलब्धता की हानि का सीमित प्रभाव होता है।
• मध्यम: इसका गंभीर प्रभाव होता है।
• उच्च: इसका विनाशकारी प्रभाव होता है।',
    // Base Score Metrics' two sub-group intro sentences (metricsSubGroup()'s
    // `descKey`, risk-details-form.js) -- orient the user to what the GROUP
    // as a whole is asking, distinct from the per-field *Help popover keys
    // above which explain each metric's own options.
    'BaseScoreExploitabilityMetricsDescription' => 'हमलावर को इस भेद्यता तक पहुँचने और इसे सक्रिय करने के लिए क्या करना होगा: उसे कहाँ होना चाहिए, हमला कितना जटिल है, और क्या उसे पहले प्रमाणीकरण करना होगा।',
    'BaseScoreImpactMetricsDescription' => 'यदि इस भेद्यता का सफलतापूर्वक फायदा उठाया जाता है तो क्या होगा: प्रभावित सिस्टम की गोपनीयता, अखंडता और उपलब्धता पर क्या प्रभाव पड़ेगा।',
    // Advanced Metrics' three optional sub-group intro sentences -- same
    // metricsSubGroup() `descKey` as the two Base Score groups above.
    'TemporalScoreMetricsDescription' => 'समय के साथ इस भेद्यता का वास्तविक दुनिया में खतरा कैसे बदलता है: एक्सप्लॉइट कोड की वर्तमान स्थिति, उपलब्ध निवारण उपाय और इसके अस्तित्व के बारे में रिपोर्टों की विश्वसनीयता।',
    'EnvironmentalScoreMetricsDescription' => 'इस भेद्यता का जोखिम आपके परिवेश पर कैसे निर्भर करता है: वास्तविक दुनिया में नुकसान की संभावना, और आपके कितने सिस्टम वास्तव में प्रभावित हैं।',
    'ImpactSubscoreModifiersDescription' => 'बेस स्कोर के प्रभाव को इस आधार पर भारित करें कि इस विशिष्ट एसेट के लिए गोपनीयता, अखंडता और उपलब्धता वास्तव में कितनी मायने रखती हैं।',
    // Phase 4d-iii: DREAD holder help popovers (view_dread_help()'s
    // existing English text, includes/display.php, extracted to real $lang
    // keys -- that function's own content was raw hardcoded HTML, never
    // localized, so it could not be reused verbatim).
    'DamagePotentialHelp' => 'यदि किसी खतरे का शोषण होता है, तो कितनी क्षति होगी?
0 = कुछ नहीं
5 = व्यक्तिगत उपयोगकर्ता का डेटा समझौता-ग्रस्त या प्रभावित होता है।
10 = सिस्टम या डेटा का पूर्ण विनाश',
    'ReproducibilityHelp' => 'इस खतरे के शोषण को दोहराना कितना आसान है?' . "\n" . '0 = बहुत कठिन या असंभव, यहां तक कि एप्लिकेशन के प्रशासकों के लिए भी।' . "\n" . '5 = एक या दो चरणों की आवश्यकता है, अधिकृत उपयोगकर्ता होना आवश्यक हो सकता है।' . "\n" . '10 = प्रमाणीकरण की आवश्यकता नहीं है, केवल एक वेब ब्राउज़र और एड्रेस बार ही पर्याप्त है।',
    'ExploitabilityHelp' => 'इस खतरे का शोषण करने के लिए क्या आवश्यक है?
0 = उन्नत प्रोग्रामिंग और नेटवर्किंग ज्ञान, कस्टम या उन्नत हमला टूल के साथ।
5 = इंटरनेट पर मैलवेयर मौजूद है, या उपलब्ध हमला टूल से शोषण आसानी से किया जा सकता है।
10 = केवल एक वेब ब्राउज़र',
    'AffectedUsersHelp' => 'कितने उपयोगकर्ता प्रभावित होंगे?' . "\n" . '0 = कोई नहीं' . "\n" . '5 = कुछ उपयोगकर्ता, लेकिन सभी नहीं' . "\n" . '10 = सभी उपयोगकर्ता',
    'DiscoverabilityHelp' => 'इस खतरे का पता लगाना कितना आसान है?' . "\n" . '0 = बहुत कठिन से असंभव; इसके लिए सोर्स कोड या प्रशासनिक पहुँच की आवश्यकता है।' . "\n" . '5 = अनुमान लगाकर या नेटवर्क ट्रेस की निगरानी करके इसका पता लगाया जा सकता है।' . "\n" . '9 = इस तरह की खामियों का विवरण पहले से ही सार्वजनिक डोमेन में है और इसे सर्च इंजन का उपयोग करके आसानी से खोजा जा सकता है।' . "\n" . '10 = जानकारी वेब ब्राउज़र के एड्रेस बार में या किसी फॉर्म में दिखाई देती है।',
    // The DREAD holder's summary card heading and "DREAD Metrics" card
    // heading. No existing key covers either (confirmed via grep before
    // adding).
    'DreadScore' => 'DREAD स्कोर',
    'DreadMetrics' => 'DREAD मेट्रिक्स',
    // Phase 4d-iv: OWASP holder help popovers (view_owasp_help()'s
    // existing English text, includes/display.php, extracted to real
    // $lang keys -- same never-localized-legacy-content extraction the
    // DREAD phase already did for its own 5 fields). Wording/levels
    // trued up against that function's real source text, not transcribed
    // from an earlier standard-methodology draft.
    'SkillLevelHelp' => 'खतरा एजेंटों का यह समूह तकनीकी रूप से कितना कुशल है?
1 = कोई तकनीकी कौशल नहीं
3 = कुछ तकनीकी कौशल
5 = उन्नत कंप्यूटर उपयोगकर्ता
6 = नेटवर्क और प्रोग्रामिंग कौशल
9 = सुरक्षा पेनिट्रेशन कौशल',
    'MotiveHelp' => 'खतरा एजेंटों का यह समूह इस भेद्यता को खोजने और उसका शोषण करने के लिए कितना प्रेरित है?
1 = कम या कोई पुरस्कार नहीं
4 = संभावित पुरस्कार
9 = उच्च पुरस्कार',
    'OpportunityHelp' => 'खतरा एजेंटों के इस समूह को इस भेद्यता को खोजने और उसका शोषण करने के लिए किन संसाधनों और अवसर की आवश्यकता है?
0 = पूर्ण पहुँच या महँगे संसाधन आवश्यक
4 = विशेष पहुँच या संसाधन आवश्यक
7 = कुछ पहुँच या संसाधन आवश्यक
9 = किसी पहुँच या संसाधन की आवश्यकता नहीं',
    'SizeHelp' => 'खतरे पैदा करने वाले इन एजेंटों का समूह कितना बड़ा है?' . "\n" . '2 = डेवलपर्स' . "\n" . '2 = सिस्टम प्रशासक' . "\n" . '4 = इंट्रानेट उपयोगकर्ता' . "\n" . '5 = साझेदार' . "\n" . '6 = प्रमाणित उपयोगकर्ता' . "\n" . '9 = गुमनाम इंटरनेट उपयोगकर्ता',
    'EaseOfDiscoveryHelp' => 'खतरा एजेंटों के इस समूह के लिए इस भेद्यता को खोजना कितना आसान है?
1 = व्यावहारिक रूप से असंभव
3 = कठिन
7 = आसान
9 = स्वचालित टूल उपलब्ध',
    'EaseOfExploitHelp' => 'खतरा एजेंटों के इस समूह के लिए इस भेद्यता का वास्तव में शोषण करना कितना आसान है?
1 = सैद्धांतिक
3 = कठिन
5 = आसान
9 = स्वचालित टूल उपलब्ध',
    'AwarenessHelp' => 'खतरा एजेंटों के इस समूह को यह भेद्यता कितनी अच्छी तरह ज्ञात है?
1 = अज्ञात
4 = छिपी हुई
6 = स्पष्ट
9 = सार्वजनिक जानकारी',
    'IntrusionDetectionHelp' => 'किसी शोषण का पता चलने की कितनी संभावना है?
1 = एप्लिकेशन में सक्रिय पहचान
3 = लॉग और समीक्षा की गई
8 = समीक्षा के बिना लॉग की गई
9 = लॉग नहीं की गई',
    'LossOfConfidentialityHelp' => 'कितना डेटा प्रकट हो सकता है और वह कितना संवेदनशील है?
2 = न्यूनतम गैर-संवेदनशील डेटा प्रकट हुआ
6 = न्यूनतम महत्वपूर्ण डेटा प्रकट हुआ
6 = व्यापक गैर-संवेदनशील डेटा प्रकट हुआ
7 = व्यापक महत्वपूर्ण डेटा प्रकट हुआ
9 = सारा डेटा प्रकट हुआ',
    'LossOfIntegrityHelp' => 'कितना डेटा दूषित हो सकता है और वह कितना क्षतिग्रस्त है?
1 = न्यूनतम, थोड़ा दूषित डेटा
3 = न्यूनतम, गंभीर रूप से दूषित डेटा
5 = व्यापक, थोड़ा दूषित डेटा
7 = व्यापक, गंभीर रूप से दूषित डेटा
9 = सारा डेटा पूरी तरह दूषित',
    'LossOfAvailabilityHelp' => 'कितनी सेवा खो सकती है और वह कितनी महत्वपूर्ण है?
1 = न्यूनतम द्वितीयक सेवाएँ बाधित
5 = न्यूनतम प्राथमिक सेवाएँ बाधित
5 = व्यापक द्वितीयक सेवाएँ बाधित
7 = व्यापक प्राथमिक सेवाएँ बाधित
9 = सभी सेवाएँ पूरी तरह खो गईं',
    'LossOfAccountabilityHelp' => 'क्या खतरा पैदा करने वाले तत्वों की गतिविधियों का पता किसी व्यक्ति से लगाया जा सकता है?' . "\n" . '1 = पूरी तरह से पता लगाने योग्य' . "\n" . '7 = संभवतः पता लगाया जा सकता है' . "\n" . '9 = पूरी तरह से गुमनाम',
    'FinancialDamageHelp' => 'किसी शोषण से कितनी वित्तीय क्षति होगी?
1 = भेद्यता को ठीक करने की लागत से कम
3 = वार्षिक लाभ पर मामूली प्रभाव
7 = वार्षिक लाभ पर महत्वपूर्ण प्रभाव
9 = दिवालियापन',
    'ReputationDamageHelp' => 'क्या किसी शोषण से प्रतिष्ठा को ऐसी क्षति होगी जो व्यवसाय को नुकसान पहुँचाए?
1 = न्यूनतम क्षति
4 = प्रमुख खातों की हानि
5 = सद्भावना की हानि
9 = ब्रांड को क्षति',
    'NonComplianceHelp' => 'अनुपालन न करने से कितना जोखिम उत्पन्न होता है?
2 = मामूली उल्लंघन
5 = स्पष्ट उल्लंघन
7 = उच्च-प्रोफ़ाइल उल्लंघन',
    'PrivacyViolationHelp' => 'कितनी व्यक्तिगत पहचान योग्य जानकारी का खुलासा किया जा सकता है?' . "\n" . '3 = एक व्यक्ति' . "\n" . '5 = सैकड़ों लोग' . "\n" . '7 = हजारों लोग' . "\n" . '9 = लाखों लोग',
    // The OWASP holder's Score card heading. No existing key covers this
