    'AssetScoringSettingsHint' => 'प्रत्येक एसेट को गोपनीयता, अखंडता और उपलब्धता के लिए निम्न, मध्यम या उच्च रेटिंग दी जाती है, और गोपनीयता के लिए इसके बजाय लागू नहीं हो सकता है, जिससे वह दोनों परिणामों से बाहर रहती है। उसका FIPS वर्गीकरण तीनों रेटिंग में से उच्चतम होता है। उसका भारित स्कोर तीनों स्तर मानों का भारित औसत होता है, और बैंड थ्रेशोल्ड उस स्कोर को निम्न, मध्यम या उच्च बैंड में बदल देते हैं। इन सेटिंग्स को बदलने पर प्रत्येक एसेट का स्कोर तुरंत दोबारा निकाला जाता है।',
    'Weights' => 'भार',
    'AssetScoringWeightsHint' => 'भारित स्कोर में प्रत्येक उद्देश्य कितना गिना जाएगा: 0 से 100, अधिकतम दो दशमलव स्थानों तक। 0 भार होने पर वह उद्देश्य बाहर रहता है। अखंडता और उपलब्धता दोनों 0 नहीं हो सकते, क्योंकि लागू न होने वाली गोपनीयता हमेशा बाहर रखी जाती है।',
    'LevelValues' => 'स्तर मान',
    'AssetScoringLevelValuesHint' => 'प्रत्येक रेटिंग भारित स्कोर में जो संख्या जोड़ती है: 0 से अधिक और अधिकतम 100 तक, अधिकतम दो दशमलव स्थानों के साथ, और निम्न < मध्यम < उच्च। डिफ़ॉल्ट मान निम्न 1, मध्यम 2 और उच्च 3 हैं।',
    'BandThresholds' => 'बैंड सीमाएँ',
    'AssetScoringBandThresholdsHint' => 'किसी थ्रेशोल्ड पर या उससे ऊपर का भारित स्कोर उसी बैंड में आता है, और मध्यम थ्रेशोल्ड से नीचे का स्कोर निम्न होता है। मध्यम निम्न मान से ऊपर शुरू होना चाहिए, और उच्च मध्यम से ऊपर तथा उच्च मान से अधिक नहीं शुरू होना चाहिए।',
    'ModerateStartsAt' => 'मध्यम इस मान से शुरू होता है',
