    'DefaultScoringForNewAssets' => 'नई संपत्तियों के लिए डिफ़ॉल्ट स्कोरिंग',
    'AssetScoringDefaultsHint' => 'जब कोई व्यक्ति एसेट फॉर्म में कोई एसेट जोड़ता है, तो ये रेटिंग पहले से ही चुन ली जाती हैं। खोज, आयात या API द्वारा बनाए गए एसेट तब तक बिना स्कोर के रहते हैं जब तक वे अपनी रेटिंग खुद नहीं देते। इसे बंद करने के लिए तीनों विकल्पों को \'सेट नहीं\' रहने दें।',
    'AssetScoringWeightsInvalid' => 'एसेट स्कोरिंग के भार 0 से 100 के बीच की संख्याएँ होने चाहिए जिनमें अधिकतम दो दशमलव स्थान हों, और अखंडता तथा उपलब्धता दोनों 0 नहीं हो सकते।',
    'AssetScoringValuesInvalid' => 'एसेट स्कोरिंग के स्तर मान 0 से अधिक और अधिकतम 100 तक की संख्याएँ होने चाहिए जिनमें अधिकतम दो दशमलव स्थान हों, और निम्न < मध्यम < उच्च होना चाहिए।',
    'AssetScoringThresholdsInvalid' => 'एसेट स्कोरिंग के बैंड थ्रेशोल्ड में अधिकतम दो दशमलव स्थान होने चाहिए, मध्यम निम्न मान से ऊपर शुरू हो, उच्च मध्यम से ऊपर शुरू हो, और उच्च उच्च मान से अधिक न हो।',
    'AssetScoringDefaultsInvalid' => 'नए एसेट के लिए डिफ़ॉल्ट स्कोरिंग ऐसा स्तर होना चाहिए जो प्रत्येक उद्देश्य में उपलब्ध हो।',
