    'ImportAssetScoringValueIgnored' => 'परिसंपत्ति "{$asset_name}" के लिए {$objective} मान "{$value}" एक वैध रेटिंग नहीं है और इसे अनदेखा कर दिया गया था।',
    'AssetScoringSecurityObjectives' => 'सुरक्षा उद्देश्य',
