    'AssetScoringResultHelpLabel' => '{$result} की व्याख्या',
    'AssetScoringScoreHelp' => 'भारित स्कोर तीनों रेटिंग को {$low} से {$high} के बीच एक संख्या में मिलाता है। प्रत्येक रेटिंग अपने निर्धारित मान में बदल जाती है, और प्रत्येक को उसके उद्देश्य के भार से गुणा किया जाता है। परिणामों को जोड़ा जाता है और भारों के कुल योग से विभाजित किया जाता है। "लागू नहीं" वाली गोपनीयता को उसके भार सहित छोड़ दिया जाता है। निर्धारित मान और भार प्राथमिकताएँ में कॉन्फ़िगर किए जाते हैं। स्कोर दिखाए जाने से पहले तीनों उद्देश्यों की रेटिंग की जानी चाहिए।',
    'AssetScoringCategorizationHelp' => 'FIPS 199 सुरक्षा वर्गीकरण उच्चतम स्तर (हाई-वॉटर मार्क) होता है: लागू होने वाले उद्देश्यों में सबसे उच्च रेटिंग। एक भी उच्च रेटिंग होने पर एसेट उच्च माना जाता है, चाहे अन्य कुछ भी हों। "लागू नहीं" को अनदेखा किया जाता है।',
    'AssetScoringBandHelp' => 'यह बैंड भारित स्कोर को निम्न, मध्यम या उच्च पैमाने पर निर्धारित करता है। {$moderate} से कम स्कोर निम्न है, {$moderate} से {$highAt} तक का स्कोर मध्यम है, और {$highAt} या उससे अधिक का स्कोर उच्च है। इन सीमाओं को वरीयताओं में कॉन्फ़िगर किया जा सकता है।',
