    'UserImportPasswordsUnavailable' => 'अस्थायी पासवर्ड अब नहीं दिखाए जा सकते। वे केवल एक बार, सिर्फ़ उस व्यवस्थापक को जिसने आयात शुरू किया था और सिर्फ़ उसी ब्राउज़र टैब में दिखाए जाते हैं जिसमें आयात शुरू किया गया था, और SimpleRisk ऐसा कुछ नहीं रखता जिससे उन्हें दोबारा दिखाया जा सके। उपयोगकर्ता को संपादित करके प्रत्येक नए उपयोगकर्ता के लिए नया पासवर्ड सेट करें।',
    'UserImportBackgroundNote' => 'यह पृष्ठ अपने आप अपडेट होता है और यदि आप इसे छोड़ दें तो भी आयात चलता रहता है। परिणाम देखने के लिए पृष्ठ को फिर से खोलें।',
    'AuditAdditionalStakeholdersSetOnTest' => 'अतिरिक्त हितधारक परीक्षण पर सेट किए जाते हैं। उन्हें बदलने के लिए {$page} के अंतर्गत परीक्षण को संपादित करें; यह बदलाव इस ऑडिट पर तुरंत लागू हो जाता है।',
    'QuestionnaireDraftSomeFilesNotSaved' => 'आपके उत्तर सहेज लिए गए हैं, लेकिन एक या अधिक अटैचमेंट सहेजे नहीं जा सके। हो सकता है कि फ़ाइल बहुत बड़ी हो या उस प्रकार की हो जिसकी अनुमति नहीं है।',
    'UploadFileTooBigForDatabase' => 'अपलोड की गई फ़ाइल डेटाबेस में स्टोर करने के लिए बहुत बड़ी है। SimpleRisk एडमिनिस्ट्रेटर MySQL कॉन्फ़िगरेशन में max_allowed_packet और innodb_log_file_size के मान बढ़ा सकता है।',
