    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'HTTP स्ट्रिक्ट ट्रांसपोर्ट सिक्योरिटी (HSTS) को सक्षम करें',
    'EnableHSTSHelp' => 'यह ब्राउज़रों को नीचे दी गई अधिकतम अवधि तक SimpleRisk से केवल HTTPS के माध्यम से कनेक्ट करने का निर्देश देता है। इसे तभी सक्षम करें जब इस साइट पर HTTPS सुचारू रूप से काम कर रहा हो: जिन ब्राउज़रों ने यह हेडर देखा है, वे सामान्य HTTP को अस्वीकार कर देंगे, और अधिकतम अवधि समाप्त होने तक किसी भी दोषपूर्ण प्रमाणपत्र को बायपास नहीं किया जा सकता है। शुरुआत में अधिकतम अवधि कम रखें, जैसे कि 300 सेकंड, और HTTPS सत्यापित होने के बाद इसे बढ़ा दें।',
    'HSTSMaxAge' => 'HSTS अधिकतम अवधि (सेकंड)',
    'HSTSMaxAgeInvalid' => 'HSTS की अधिकतम अवधि 0 से 63072000 के बीच सेकंड की पूर्ण संख्या होनी चाहिए।',
    'HSTSIncludeSubdomains' => 'सभी सबडोमेन पर HSTS लागू करें',
