    'RequiredQuestionHasNoAnswerChoices' => 'यह प्रश्न आवश्यक है लेकिन इसमें कोई उत्तर विकल्प नहीं है, इसलिए उत्तरदाताओं के पास चुनने के लिए कुछ नहीं है और यह सबमिशन को ब्लॉक नहीं कर सकता। कम से कम एक उत्तर विकल्प जोड़ें, या आवश्यक को अनचेक करें।',
    'PasswordResetEmailSendFailed' => 'पासवर्ड रीसेट करने का ईमेल भेजा नहीं जा सका। कृपया ईमेल सेटिंग की जांच करने के लिए अपने SimpleRisk एडमिनिस्ट्रेटर से संपर्क करें।',
    'PasswordResetBaseUrlMismatch' => 'इस पते से पासवर्ड रीसेट करने का अनुरोध पूरा नहीं हो सका। कृपया बेस यूआरएल सेटिंग की जांच के लिए अपने SimpleRisk एडमिनिस्ट्रेटर से संपर्क करें।',
    'UploadFileTypeDetectionUnavailable' => 'इस सर्वर पर PHP fileinfo एक्सटेंशन इंस्टॉल न होने के कारण फ़ाइलें अपलोड नहीं की जा सकतीं। कृपया अपने SimpleRisk एडमिनिस्ट्रेटर से fileinfo एक्सटेंशन को सक्षम करने का अनुरोध करें।',
    'BackupDownloadInvalidRequest' => 'बैकअप डाउनलोड अनुरोध मान्य नहीं है।',
    'BackupDownloadFileNotFound' => 'बैकअप फ़ाइल सर्वर पर नहीं मिली। संभवतः इसे स्थानांतरित कर दिया गया है या हटा दिया गया है।',
    'DocumentRequiredFieldsMissing' => 'दस्तावेज़ अनुरोध में आवश्यक फ़ील्ड गायब हैं: {$fields}।',
    'DeactivationGuardFailed' => 'निष्क्रियकरण शुरू नहीं हो सका। विवरण के लिए पृष्ठ के शीर्ष भाग में दी गई चेतावनी देखें।',
    'SamlKeepRoleTeamsWhenAbsent' => 'जब IdP भूमिका या टीम एट्रिब्यूट नहीं भेजता, तब उपयोगकर्ता की वर्तमान भूमिका और टीमें बनाए रखें',
    'SamlKeepRoleTeamsWhenAbsentHelp' => 'बंद (अनुशंसित): जिस लॉगिन में एट्रिब्यूट नहीं होता, वह उपयोगकर्ता को डिफ़ॉल्ट भूमिका पर रीसेट कर देता है और कोई टीम नहीं रहती। चालू: उपयोगकर्ता अपनी वर्तमान भूमिका और टीमें बनाए रखता है। इसे केवल तभी चालू करें जब आपका IdP उन उपयोगकर्ताओं के लिए एट्रिब्यूट छोड़ देता हो जिनकी पहुँच बनी रहनी चाहिए (Microsoft Entra ऐसे उपयोगकर्ताओं के लिए ऐसा करता है जिनके पास App Role नहीं है), और ध्यान दें कि किसी उपयोगकर्ता को सभी IdP समूहों से हटाने पर SimpleRisk में उसकी भूमिका कम नहीं होगी।',
    'ImportScoringValueNotRecognizedUpdate' => 'जोखिम {$risk_id} ("{$subject}"): {$field} मान "{$value}" को पहचाना नहीं गया, इसलिए इस जोखिम की स्कोरिंग को अपरिवर्तित छोड़ दिया गया।',
    'ImportScoringValueNotRecognizedNew' => 'जोखिम {$risk_id} ("{$subject}"): {$field} मान "{$value}" को पहचाना नहीं गया और इस नए जोखिम पर लागू नहीं किया गया।',
    'SelectAFileToImport' => 'आयात करने के लिए एक फ़ाइल चुनें।',
    'PasswordResetEmailSentToUser' => 'उपयोगकर्ता को पासवर्ड रीसेट करने का ईमेल भेजा गया।',
    'UnlockAccount' => 'अनलॉक',
    'AccountUnlocked' => 'खाता अनलॉक कर दिया गया है।',
    'AccountWasNotLocked' => 'खाता लॉक नहीं था।',
    'AccountLockedOutHelp' => 'बहुत अधिक विफल साइन-इन प्रयासों के बाद, या उपयोगकर्ता द्वारा पासवर्ड रीसेट पूरा करने तक, यह खाता लॉक रहता है। उपयोगकर्ता को फिर से साइन इन करने देने के लिए इसे अनलॉक करें। किसी को बाहर रखने के लिए, इसके बजाय खाते को अक्षम करें। अनलॉक करने से इस पृष्ठ पर कुछ और सहेजा नहीं जाता।',
    'ControlIdAsDisplayed' => 'नियंत्रण आईडी (जैसा प्रदर्शित है)',
    'ControlIdNotADisplayedId' => 'पंक्ति छोड़ी गई: "{$id}" प्रदर्शित नियंत्रण आईडी नहीं है। प्रदर्शित आईडी 1001 से शुरू होती हैं; वर्तमान आईडी प्राप्त करने के लिए नियंत्रणों को पुनः निर्यात करें।',
    'ControlIdNotFound' => 'पंक्ति छोड़ दी गई: ID "{$id}" वाला कोई नियंत्रण प्रदर्शित नहीं है।',
    'MappedControlFrameworksInvalid' => 'मैप किए गए नियंत्रण फ़्रेमवर्क का मान [{"framework":"","reference_name":"","reference_text":"","reference_subject":""}] रूप में वैध JSON नहीं है, इसलिए उस पंक्ति के लिए इसे अनदेखा कर दिया गया।',
    'ControlApplicability' => 'नियंत्रण प्रयोज्यता',
    'ControlApplicabilityInvalid' => 'नियंत्रण प्रयोज्यता का मान [{"framework":"","state":"","narrative":"","provider":"","reasons":[]}] रूप में वैध JSON नहीं है, इसलिए उस पंक्ति के लिए इसे अनदेखा कर दिया गया।',
    'ControlApplicabilityUnsupported' => 'SimpleRisk का यह संस्करण नियंत्रण प्रयोज्यता का समर्थन नहीं करता है, इसलिए नियंत्रण प्रयोज्यता मान को अनदेखा कर दिया गया।',
    'ControlApplicabilityNoPermission' => 'नियंत्रण प्रयोज्यता को अनदेखा कर दिया गया क्योंकि आपका खाता फ्रेमवर्क को संशोधित नहीं कर सकता है।',
    'ControlApplicabilityFrameworkNotFound' => 'फ्रेमवर्क "{$framework}" के लिए प्रयोज्यता लागू नहीं की गई: ऐसा कोई फ्रेमवर्क मौजूद नहीं है।',
    'ControlApplicabilityReasonNotFound' => 'फ़्रेमवर्क "{$framework}" के लिए प्रयोज्यता लागू नहीं की गई: "{$reason}" कोई ज्ञात कारण नहीं है।',
    'ControlApplicabilityNotApplied' => 'फ्रेमवर्क "{$framework}" के लिए प्रयोज्यता लागू नहीं की गई: {$message}',
    'PreviouslyAnsweredOptionChanged' => 'पहले उत्तर दिया गया; यह विकल्प बाद में बदला गया या हटाया गया',
    'PreviouslyAnsweredChooseAgain' => 'पहले उत्तर दिया गया था, लेकिन वह विकल्प बाद में बदला गया या हटाया गया। कृपया फिर से चुनें:',
    'PendingRiskScoreCouldNotBeRendered' => 'इस लंबित जोखिम के लिए स्कोर अनुभाग प्रदर्शित नहीं किया जा सका। विवरण के लिए SimpleRisk लॉग देखें।',
    'QuestionnaireResultNotReopenableUndecided' => 'प्रश्नावली परिणाम को फिर से नहीं खोला जा सकता क्योंकि उसे स्वीकृत, अस्वीकृत या "स्वीकृत नहीं" के रूप में चिह्नित नहीं किया गया है।',
    'ControlIdLegacyDatabaseId' => 'नियंत्रण ID (डेटाबेस ID, पुराना निर्यात)',
    'ControlIdLegacyColumnNotice' => 'इस फ़ाइल में पुराने नियंत्रण आईडी कॉलम का उपयोग किया गया है, जिसमें SimpleRisk द्वारा प्रदर्शित आईडी के बजाय डेटाबेस की मूल आईडी मौजूद हैं। इन आईडी का मिलान डेटाबेस आईडी के रूप में किया गया है। भविष्य में आयात के लिए प्रदर्शित आईडी ("नियंत्रण आईडी (जैसा प्रदर्शित है)" कॉलम) प्राप्त करने के लिए नियंत्रणों को पुनः निर्यात करें।',
    'ControlIdLegacyNotFound' => 'पंक्ति छोड़ी गई: डेटाबेस आईडी "{$id}" वाला कोई नियंत्रण नहीं है।',
    'ControlIdHeaderIsLegacy' => 'कुछ नहीं आयात किया गया। "नियंत्रण ID (जैसा प्रदर्शित है)" से मैप किए गए कॉलम का शीर्षक "नियंत्रण ID" है, जो पहले के संस्करण द्वारा निर्यात किए गए नियंत्रणों में उनकी डेटाबेस ID को दिया जाने वाला लेबल है। इसके बजाय उस कॉलम को "नियंत्रण ID (डेटाबेस ID, पुराना निर्यात)" से मैप करें, या प्रदर्शित ID प्राप्त करने के लिए नियंत्रणों को फिर से निर्यात करें। यदि कॉलम में 1001 या उससे अधिक की ID हैं, तो वह प्रदर्शित-ID कॉलम है: उसके शीर्षक का नाम बदलकर "नियंत्रण ID (जैसा प्रदर्शित है)" करें और उसे फिर से मैप करें।',
    'ControlIdHeaderIsDisplayed' => 'कुछ नहीं आयात किया गया। "नियंत्रण ID (डेटाबेस ID, पुराना निर्यात)" से मैप किए गए कॉलम का शीर्षक "नियंत्रण ID (जैसा प्रदर्शित है)" है, इसलिए उसमें प्रदर्शित ID हैं। इसके बजाय उस कॉलम को "नियंत्रण ID (जैसा प्रदर्शित है)" से मैप करें।',
